<?php include "db.php";$from=trim($_GET['from']??'');$to=trim($_GET['to']??'');$date=$_GET['date']??'';$sql="SELECT * FROM buses WHERE travel_date >= CURDATE()";$types="";$params=[];if($from!==""){$sql.=" AND source LIKE ?";$types.="s";$params[]="%$from%";}if($to!==""){$sql.=" AND destination LIKE ?";$types.="s";$params[]="%$to%";}if($date!==""){$sql.=" AND travel_date = ?";$types.="s";$params[]=$date;}$sql.=" ORDER BY travel_date,departure_time";$stmt=mysqli_prepare($conn,$sql);if($types!=="")mysqli_stmt_bind_param($stmt,$types,...$params);mysqli_stmt_execute($stmt);$buses=mysqli_stmt_get_result($stmt);?>
<!DOCTYPE html><html><head><title>Find Buses</title><link rel="stylesheet" href="style.css"></head><body><header><h1>GoBus</h1><nav><a href="index.php">Home</a><a href="buses.php">Find Buses</a><a href="my_bookings.php">My Tickets</a><a href="dashboard.php">Dashboard</a></nav></header><div class="container"><div class="form-box"><h2>Search Buses</h2><form method="get"><label>From</label><input name="from" value="<?php echo htmlspecialchars($from); ?>" placeholder="e.g. Chennai"><label>To</label><input name="to" value="<?php echo htmlspecialchars($to); ?>" placeholder="e.g. Bengaluru"><label>Travel date</label><input type="date" name="date" min="<?php echo date('Y-m-d'); ?>" value="<?php echo htmlspecialchars($date); ?>"><button>Search</button></form></div><h2>Available Buses</h2><div class="grid"><?php while($b=mysqli_fetch_assoc($buses)){?><div class="room"><h3><?php echo htmlspecialchars($b['bus_name']); ?></h3><p><?php echo htmlspecialchars($b['category']); ?></p><p><b><?php echo htmlspecialchars($b['source']); ?> → <?php echo htmlspecialchars($b['destination']); ?></b></p><p>Date: <?php echo $b['travel_date']; ?></p><p>Departure: <?php echo $b['departure_time']; ?></p><p>Available seats: <?php echo (int)$b['available_seats']; ?></p><h3>₹<?php echo number_format($b['price'],2); ?> / seat</h3><a class="btn" href="book.php?bus_id=<?php echo $b['id']; ?>">Book Seat</a></div><?php } ?></div></div></body></html>